def find_powers_of_5(n):
    powers = []
    num = 1
    while num < n:
        powers.append(num)
        num *= 5
    return powers

def factorial_mod(n, mod):
    ans = 1
    for i in range(2, n+1):
        ans = (ans * i) % mod
    return ans

def combination_mod(n, k, mod):
    return factorial_mod(n, mod) * pow(factorial_mod(k, mod), mod-2, mod) * pow(factorial_mod(n-k, mod), mod-2, mod) % mod

