import bisect

def minimize_brackets(sequence):
    def can_form_sequence(positions):
        """Check if it's possible to form the sequence from given positions"""
        balanced = deque()
        open_brackets = 0
        for i, pos in enumerate(positions):
            if i > len(sequence) - 1:
                break
            if sequence[i] == '(':
                if pos > i:
                    balanced.append(pos)
                    open_brackets += 1
                else:
                    return False
            elif sequence[i] == ')' and open_brackets > 0:
                balanced.rotate(-1)
                open_brackets -= 1
            else:
                return False
            if len(balanced) > 0 and balanced[0] < i:
                return False
        if balanced:
            return False
        return True

    def find_insertion_point(index_start):
        """Find the insertion point to ensure minimum length sequence"""
        low, high = 0, len(sequence)
        while low < high - 2:
            mid = low + (high - low) // 2
            if can_form_sequence(positions[:mid]):
                low = mid + 1
            else:
                high = mid
        return low == len(sequence) or (positions[low - 1] > index_start and low != len(sequence))

    for low in range(len(sequence)):
        positions = [low]
        for r in range(len(sequence), -1, -1):
            new_position = r + low
            index_start = max(
                0, new_position - r - (min(r, low + r) - (r if r > low else 0)) + "()".find('(') + 1)
            if find_insertion_point(index_start):
                insert_start = index_start
                for i in range(len(sequence) - 1, low, -1):
                    new_position = i + low
                    index_start = max(
                        0, new_position - r -
                        (min(r, low + r) - (r if r > low else 0)) + "()".find('(') + 1
                    )
                    if find_insertion_point(index_start):
                        insert_start = min(index_start, insert_start)
                        break
                positions.append(insert_start)
            else:
                break
        if can_form_sequence(positions):
            break
    sequence_positions = []
    for pos in positions:
        if "()" in sequence[:pos]:  # to ensure everything is matching lexicographically totaly best
            break
        else:
            sequence_positions.append(pos)
    return ''.join(sequence[:i] + '(' + sequence[insert_start:] for i, insert_start in zip(positions, sequence_positions))

# Example usage
