from collections import defaultdict

def find_strength(parent, child):
    M = 0
    max_strength = 0
    group_dict = defaultdict(set)

    # Group children by parent
    for grandparent, grandchild in parent.items():
        group_dict[grandparent].add(grandchild)

    for grandchild in child.values():
        if grandchild not in parent.keys():
            group_dict[grandchild].add(grandchild)

    for group, children in group_dict.items():
        if children:
            group_set = set(children)
            for current_child in children:
                M = max(M, len(group_set & parent[current_child]) - len(group_set))
        max_strength = max(max_strength, len(children) - M)

    # Main split
    group1 = set([child for child in child.keys() if child in parent.keys()])
    for group, children in group_dict.items():
        if group1 != children:
            M = max(M, len(group_set & parent[group]) - len(group_set))
    return max_strength


