def count_good_permutations(n, m, k, p):
    mod = 10007
    total_count = 0
    for perm in permutations(range(1, n + 1)):
        max_counts = {}
        good_permutations = 0
        for i in range(1, len(perm)):
            if perm[i] > perm[i - 1]:
                max_counts[perm[i]] = max_counts.get(perm[i], 0) + 1
            elif perm[i - 1] > perm[i]:
                max_counts[perm[i]] = 1
                good_permutations += 1
        if good_permutations == k:
            total_count = total_count * 2 - (max_counts[perm[0]]* (len(perm) - 1 - max_counts[perm[0]]))
            total_count = total_count % mod
    return total_count % p

