def apply_swaps(A, Z):
    N = len(A)
    for _ in range(Z):
        new_A = [0] * N
        for i in range(1, N):
            if A[i-1] == 0 and A[i] == 1:
                new_A[i-1], new_A[i] = 1, 0
        if new_A != A:
