from heapq import heappush, heappop

def find_min_sequence(s):
    unpaired = []
    result = []
    open_bracket = False

    for char in s:
        if char == '(':
            if not open_bracket:
                unpaired.append(1)
                open_bracket = True
            else:
                heappush(unpaired, 0)
                open_bracket = False
        if char == ')' and not open_bracket:
            if unpaired:
                result.append(1)
                heappop(unpaired)
            else: 
                result.append(2)
                # Continue searching for a matching open bracket using multiset
                open_bracket = True
                while unpaired and unpaired[0] == 0:
                    v = heappop(unpaired)
                    if v == 1:
                        result.append(2)
                    else:
                        heappush(unpaired, v+1)
    if open_bracket:
        result.append(1)
    while unpaired and unpaired[0] == 0:
        result.append(2)
        heappop(unpaired)
    result += heappop(unpaired)
    result.reverse()
    return ''.join(map(str, result))

