def kruskal_strength(n, edges):
    parent = {i: i for i in range(1, n + 1)}
    forest_edges = []
    forest_strengths = [0] * n
    strength = 0

    edges.sort()

    for u, v in edges:
        if find_parent(parent, u) != find_parent(parent, v):
            union_parent(parent, u, v)
            forest_edges.append((u, v, u > v, u < v))
            if u <= v:
                strength += 1

    minimum_strengths = [float('inf')] * n
    for u, v, l, r in forest_edges:
        if l:
            strength -= r
            minimum_strengths[u] = min(minimum_strengths[u], strength)
            minimum_strengths[v] = min(minimum_strengths[v], strength)
