            if minimum_strengths[u] < minimum_strengths[v]:
                minimum_strengths[v] = min(minimum_strengths[v], strength - 1 + r)
            else:
                minimum_strengths[u] = min(minimum_strengths[u], strength - 1 + r)

    return minimum_strengths

