from math import sqrt

def divisors(n):
    """Return a sorted list of divisors of n."""
    if n == 1 or (n % 2 == 1 and n == 3):
        return [1, n]
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            yield i
            n //= i
    if n > 1:
        yield n

def sieve(n):
    """Return a dictionary of divisors of integers from 1 to n."""
    d = {1:1, n:1}
    sieve = list(range(n + 1))
    sieve[0] = sieve[1] = 0
    for i in sieve:
        if i <= n:
            d[i] = 2 * d[i - 1]
            for j in range(i * 2, n + 1, i):
                d[j] = d[j] - d[i-1]
                if d[j]:
                    div = divisors(j)
                    d[j] = div.sort()[-1]
                    del d[div[0]]
    return d        

