def min_stem_sequence(sequence):
    stack = []
    while parentheses(sequence):
        next_letter = next_sequence([char for char in sequence if char == '(' or char == ')'])
        if (next_letter == '(' and stack and stack[-1] == ')') or (next_letter == ')' and stack and stack[-1] == '('):
            stack.pop()
        else:
            stack.append(next_letter)
    return ''.join(stack).replace('()', '')

def next_sequence(sequence):
    while True:
        yield from sequence

def parentheses(sequence):
    length = len(sequence)
    for i in range(length + 1):
        yield from [sequence[j - 1] + sequence[j] for j in range(i, length) if sequence[i] != '()'][::-1]

