# Function to generate prime numbers up to a given limit
def sieve(limit, prime_factors):
    yield from map(lambda x: x << 1, filter(lambda x: x % prime_factors == 0, range(limit, 2 * limit, prime_factors)))

def generate_primes(prime_factors, max_prime_factor):
    primes_array = []
    prime_numbers = []
    limit = 1

    # Generate prime numbers up to the maximum prime factor
    for prime_number in sieve(max_prime_factor, prime_factors):
        if prime_number in primes_array:
            continue
        prime_numbers.append(prime_number)
        for multiple in sieve(2 * limit, prime_factors):
            if multiple not in primes_array:
                limit = multiple

    return primes_array, prime_numbers

