from heapq import heappop, heappush
from collections import defaultdict

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return distances

def optimize_towns(connections, s, t):
    # Create a graph where each pair of cities is connected by a bidirectional road
    graph = defaultdict(dict)
    for city1, city2, cost in connections:
        graph[city1][city2] = cost
        graph[city2][city1] = cost

    # Remove the first and second closest direct connections between S and T for the optimization
    if s in graph[t] and t not in graph[s]:
        del graph[s][t]
    if t in graph[s] and s not in graph[t]:
        del graph[s][t]

    # Remove the first distant connection between S and T in order to improve the decision for distance
    # (in the optimized graph from step 4.2)
    if len(graph) >= 2 and graph[s][graph[s].keys()[0]]:
        del graph[s][graph[s].keys()[0]]
    elif len(graph) >= 2 and graph[t][graph[t].keys()[0]]:
        del graph[t][graph[t].keys()[0]]

    # Perform Dijkstra's algorithm to find the shortest paths from the start city
    s_distances = dijkstra(graph, s)

    # Calculate the minimum cost to get between the two cities
    result_cost = min(s_distances[city1] + s_distances[city2] for city1 in graph[s] for city2 in graph[s])

    return result_cost[:2] if result_cost else -1

if __name__ == "__main__":
    n, m = map(int, input().split())
    s, t = map(int, input().split())

    connections = [list(map(int, input().split())) for _ in range(m)]

    cost = optimize_towns(connections, s, t)

    if cost == -1:
        print("-1")
    else:
        print(cost[:2])
