def lcm(a, b):
    return a * b // math.gcd(a, b)

def phi(n):
    count = n
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            count -= count // i
            while n % i == 0:
                n //= i
    if n > 1:
        count -= count // n
    return count

def analytic_sqrt(a, p):
    b = pow(2, p - 2, p)
    return (pow(a, (p + 1) // 4, p) * pow(2, phi(p) // 4, p) * pow(b, phi(p) // 4, p)) % p

def count_good_permutations(n, m, k, p):
    if m == k:
        if n % 2 == 0:
            return pow(2, n // 2, p)
        else:
            return 2 * pow(2, n // 2 - 1, p)
    if m < k or m > n:
        return 0
    if m == 1 and n == 1:
        return 1
    if m == 1 and n == 2:
        return 0
    if m == 2:
        return lcm(n - 1, m + 1) % p
    if m == n - 1:
        return lcm(n - 1, k + 1) % p
    if n < m or n > k:
        return 0
    a = analytic_sqrt(m, p)
    res = 1
    for i in range(n):
        res = res * pow(a, k + 1 - (i + 1), p) % p
    return res * pow(a, (p + 1) // 4, p) % p * pow(a, phi(p) // 4, p) % p

