from math import pow

def count_good_permutations(n, m, k, p):
    if m < k:
        return 0  # Not enough subsequences to have exactly m different maxima

    if n == k:
        return pow(p - 1, m, p)  # If the permutation is n, all subsets will have exactly m maxima

    if m == 1:
        return pow(n, k - 1, p)  # If m=1, k>1, one such permutation exists for every subset (subset in range (k-1))
    elif m > 1 and k == n:
        return pow(p - m + 1, (((p - m + 1 - 1) // 2) + (m - 1), p - 1, p) * (pow(p, k - m, p) - 1), p)  # Subtract consecutive divisors
    elif k > 1 and m > 1:
        return pow(p, pow(p, k, m - 1, p - 1), p)  # Permutations as sums of delta's as we iterate
    else:
        return pow(p, n, p)  # Verify permutation as sums preferable

