def min_sequence_brackets(seq):
    stack = []
    result = []
    while seq:
        if seq[-1] == "(":
            stack.append(1)
        else:
            if len(stack) == 0:
                stack.append(1)
                continue
            if stack[-1] == 1:
                result.append(seq[0])
                stack.pop()
            elif stack[-1] == 0:
                stack.pop()
                while stack and stack[-1] == 0:
                    result.append(seq.pop(0))
                    stack.pop()
            result.append(")")
            seq = seq[1:] + ")" * len(stack)

    while len(stack) > 0:
        result.append(")")
        stack.pop()
        while len(stack) > 0 and stack[-1] == 0:
            result.append(seq.pop(0))
            stack.pop()
    return "".join(result)

